ccess point inside the Agent- Core Runtime. The path must be under /mnt with exactly one subdirectory level (for example, /mnt/data ). Constraints: o min: 6 o max: 200 o pattern: /mnt/[a-zA-Z0-9._-]+/? capacityProviderVolume -&gt; (structure) Configuration for a capacity provider volume to mount into the AgentCore Runtime. This mounts a persistent volume that is defined on the capacity provider, referenced by its logi- cal name. volumeName -&gt; (string) [required] The logical name of the capacity provider volume to mount. This name must match a volume that is defined in the capacity provider's list of volumes. Constraints: o min: 1 o max: 48 o pattern: [a-zA-Z][a-zA-Z0-9_-]{0,47} mountPath -&gt; (string) [required] The mount path for the capacity provider volume inside the AgentCore Runtime. The path must be under /mnt with exactly one subdirectory level (for example, /mnt/data ). Constraints: o min: 6 o max: 200 o pattern: /mnt/[a-zA-Z0-9._-]+/? Shorthand Syntax: sessionStorage={mountPath=string},s3FilesAccessPoint={accessPointArn=string,mountPath=string},efsAccessPoint={accessPointArn=string,mountPath=string},capacityProviderVolume={volumeName=string,mountPath=string} ... JSON Syntax: [ { "sessionStorage": { "mountPath": "string" }, "s3FilesAccessPoint": { "accessPointArn": "string", "mountPath": "string" }, "efsAccessPoint": { "accessPointArn": "string", "mountPath": "string" }, "capacityProviderVolume": { "volumeName": "string", "mountPath": "string" } } ... ]
    /// </summary>
    [CliOption("--filesystem-configurations", GroupValues = true)]
    public IEnumerable<string>? FilesystemConfigurations { get; set; }

    /// <summary>
    /// The capacity provider configuration for the AgentCore Runtime. Use a capacity provider to run the AgentCore Runtime on the Instances com- pute type, which provisions Amazon Web Services managed compute in your account. capacityProviderArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the capacity provider to use for the AgentCore Runtime. Constraints: o pattern: arn:aws(-[^:]+)?:bedrock-agent- core:[a-z0-9-]+:[0-9]{12}:capac- ity-provider/[a-zA-Z][a-zA-Z0-9_]{0,47}-[a-zA-Z0-9]{10} Shorthand Syntax: capacityProviderArn=string JSON Syntax: { "capacityProviderArn": "string" }
    /// </summary>
    [CliOption("--capacity-provider-configuration")]
    public string? CapacityProviderConfiguration { get; set; }

    /// <summary>
    /// A map of tag keys and values to assign to the agent runtime. Tags enable you to categorize your resources in different ways, for exam- ple, by purpose, owner, or environment. Constraints: o min: 0 o max: 50 key -&gt; (string) Constraints: o min: 1 o max: 128 o pattern: [a-zA-Z0-9\s._:/=+@-]* value -&gt; (string) Constraints: o min: 0 o max: 256 o pattern: [a-zA-Z0-9\s._:/=+@-]* Shorthand Syntax: KeyName1=string,KeyName2=string JSON Syntax: {"string": "string" ...}
    /// </summary>
    [CliOption("--tags", CollectionSeparator = ",")]
    public IReadOnlyList<KeyValue>? Tags { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

    }

